   "path": "apps/draw-guess/ui-words.ts",
   "text": "import { msg } from \"potyro\";\n// Every word the screens say, in the app's six languages (#303). English is the source; the other\n// five are a model's draft, as in the other hero apps (#297). ICU messages where a number or a name\n// goes in: `ctx.t(W.round, { n, total })`.\nimport type { Words } from \"potyro\";\n\nexport const W = {\n  appName: msg(\"Draw & Guess\"),\n  heroTitle: msg(\"Draw it. Guess it!\"),\n  tagline: msg(\"One draws, everyone guesses. First to get it scores.\"),\n  yourName: msg(\"Your name\"),\n  namePlaceholder: msg(\"What should we call you?\"),\n  needName: msg(\"Type your name first.\"),\n  newGame: msg(\"New game\"),\n  newGameHint: msg(\"You get a code to send to your friends.\"),\n  haveCode: msg(\"Got a code?\"),\n  codeLabel: msg(\"Game code\"),\n  join: msg(\"Join\"),\n  badCode: msg(\"A code is 12 letters and numbers, like KQ7M-XR4P-2DHC.\"),\n  friendsTitle: msg(\"How friends join\"),\n  friendsStep1: msg(\"Start a new game and tap Invite friends: it sends a link that opens the game with its code.\"),\n  friendsStep2: msg(\"A friend without the game taps Keep this app and lets it run as theirs. The drawing board is the app's own code, which Potyro runs only for apps you call yours — and anyone can read it first.\"),\n  friendsStep3: msg(\"The link lands on the game with the code filled in: they tap Join. Typing the code works too.\"),\n  joinGame: msg(\"Join the game\"),\n  ownGame: msg(\"Start your own game instead\"),\n  invitedTo: msg(\"You're invited to play. Say your name and join.\"),\n  invited: msg(\"You're invited to a game. Say your name and tap Join.\"),\n  connecting: msg(\"Opening the game…\"),\n  joining: msg(\"Saying hello…\"),\n  reconnecting: msg(\"Lost the connection. Trying again…\"),\n  away: msg(\"You stepped out of the game\"),\n  awayBody: msg(\"Potyro closes the game's connection when you leave the app or put it away for a while. Your score waits for you.\"),\n  rejoin: msg(\"Rejoin\"),\n  back: msg(\"Back\"),\n  nobody: msg(\"Nobody is playing with that code right now. Check it, or start a new game.\"),\n  full: msg(\"That game is full: 16 players already.\"),\n  offline: msg(\"You're offline. Connect to the internet and try again.\"),\n  unreachable: msg(\"Potyro's rooms can't be reached right now. Try again in a moment.\"),\n  denied: msg(\"Draw & Guess wasn't allowed to use Potyro's rooms. It asks again next time.\"),\n  refused: msg(\"The game wouldn't open. Try again.\"),\n  idle: msg(\"The game closed after 30 minutes with nothing happening.\"),\n  unavailable: msg(\"Live games aren't available here: this Potyro has no rooms.\"),\n  sealed: msg(\"Draw & Guess needs to run as yours: its drawing board is the app's own code.\"),\n  lobbyTitle: msg(\"Waiting for players\"),\n  shareCode: msg(\"Read it out, or send it:\"),\n  invite: msg(\"Invite friends\"),\n  inviteTitle: msg(\"Play Draw & Guess with me\"),\n  inviteText: msg(\"Come play Draw & Guess with me! Open the link to join — or, in Potyro, open Draw & Guess, tap Join and type the code {code}\"),\n  players: msg(\"{n, plural, one {# player} other {# players}}\"),\n  you: msg(\"you\"),\n  host: msg(\"host\"),\n  awayTag: msg(\"away\"),\n  wordsIn: msg(\"Words in\"),\n  rounds: msg(\"Rounds\"),\n  seconds: msg(\"Seconds to draw\"),\n  start: msg(\"Start the game\"),\n  needTwo: msg(\"It takes two. Invite someone!\"),\n  waitingHost: msg(\"{name} starts the game when everyone's in.\"),\n  leave: msg(\"Leave\"),\n  leaveSure: msg(\"Leave the game?\"),\n  leaveDetail: msg(\"The others play on without you.\"),\n  stay: msg(\"Stay\"),\n  round: msg(\"Round {n} of {total}\"),\n  choose: msg(\"Pick a word to draw\"),\n  chooseAuto: msg(\"Only you can see these. If you wait, the first one is chosen for you.\"),\n  yourTurn: msg(\"Your turn to draw!\"),\n  choosing: msg(\"{name} is picking a word…\"),\n  drawThis: msg(\"Draw\"),\n  isDrawing: msg(\"{name} is drawing\"),\n  guessPlaceholder: msg(\"Type your guess…\"),\n  guessSend: msg(\"Guess\"),\n  drawerWaits: msg(\"The others are guessing. Keep drawing!\"),\n  close: msg(\"“{text}” is so close!\"),\n  got: msg(\"{name} guessed it!\"),\n  gotYou: msg(\"You guessed it!\"),\n  joined: msg(\"{name} joined\"),\n  left: msg(\"{name} left\"),\n  wordWas: msg(\"The word was\"),\n  timeUp: msg(\"Time's up!\"),\n  drawerLeft: msg(\"{name} left, so on to the next turn.\"),\n  skipped: msg(\"{name} didn't pick a word in time.\"),\n  nextUp: msg(\"Next up: {name}\"),\n  finalTitle: msg(\"Game over!\"),\n  winner: msg(\"{name} wins!\"),\n  winnerYou: msg(\"You win!\"),\n  tie: msg(\"It's a tie!\"),\n  pts: msg(\"{n} pts\"),\n  playAgain: msg(\"Play again\"),\n  waitAgain: msg(\"{name} can start another game.\"),\n  board: msg(\"The drawing\"),\n  tools: msg(\"Pens\"),\n  black: msg(\"Black\"),\n  red: msg(\"Red\"),\n  orange: msg(\"Orange\"),\n  yellow: msg(\"Yellow\"),\n  green: msg(\"Green\"),\n  blue: msg(\"Blue\"),\n  purple: msg(\"Purple\"),\n  brown: msg(\"Brown\"),\n  eraser: msg(\"Eraser\"),\n  thin: msg(\"Thin\"),\n  medium: msg(\"Medium\"),\n  thick: msg(\"Thick\"),\n  undo: msg(\"Undo\"),\n  clear: msg(\"Clear\"),\n  soundOn: msg(\"Sounds on\"),\n  soundOff: msg(\"Sounds off\"),\n  secondsLeft: msg(\"{n, plural, one {# second left} other {# seconds left}}\"),\n  letters: msg(\"{n, plural, one {# letter} other {# letters}}\"),\n} satisfies Record<string, Words>;\n\n/** The colour names, in the order of sketch.ts's COLORS, then the eraser. */\nexport const COLOR_WORDS = [W.black, W.red, W.orange, W.yellow, W.green, W.blue, W.purple, W.brown] as const;\nexport const SIZE_WORDS = [W.thin, W.medium, W.thick] as const;\n\n/** Each language by its own name, for the room's language picker. */\nexport const LANG_NAMES = { en: \"English\", \"pt-BR\": \"Português\", de: \"Deutsch\", es: \"Español\", pl: \"Polski\", it: \"Italiano\" } as const;\n"
